// summary.js – loads data/article-summary.json, the article's numbers and map
// data. It is generated by scripts/article/tools/build-summary.mjs, which runs the
// main atlas's own LCOE worker at its default settings with 2026 costs, and is
// checked against a fresh run of that model by verify-article.mjs. The page
// itself runs no model.
//
// Format (columns, one entry per cell, location ids ascending):
//   values             every number the text and charts show, by key
//   cells.idDelta      location ids, as differences from the previous id
//   cells.lat, lon     the summary slice's site coordinates (float32, read with Math.fround)
//   cells.flags        1 = a map cell (has demand data), 2 = viable onshore wind site
//   cells.onCf         onshore capacity factor (null: none)
//   cells.country      index into cells.countries
//   cells.multiple     wind potential / local demand (null: no demand)
//   cells.windNF       share of the region's 2024 onshore wind output in Nov–Feb (null: no site)
//   cells.wl<year>     onshore wind LCOE, $/MWh, Local costs, 2026, 2035 and 2050 (null: no site)
//   results.<id>.flags 1 = priced, 2 = meets the target, 4 = solar + batteries alone meet it
//   results.<id>.*     cost with wind, without wind and the saving ($/MWh)
//                      (null where the map does not read it)
// Columns are rounded to the fewest decimals that keep every tooltip figure,
// legend bucket and colour as the model gives them.

export const SUMMARY_URL = new URL('../data/article-summary.json', import.meta.url);

const nums = (a, n) => (a ? Float64Array.from(a, x => (x == null ? NaN : x)) : new Float64Array(n).fill(NaN));
const bit = (flags, b) => Uint8Array.from(flags, f => ((f & b) ? 1 : 0));

export function decodeSummary(s) {
    const n = s.n;
    const c = s.cells;
    const ids = new Int32Array(n);
    let id = 0;
    c.idDelta.forEach((d, i) => { id += d; ids[i] = id; });
    const mapCell = bit(c.flags, 1);
    const cells = {
        n, ids,
        lat: Float64Array.from(c.lat, Math.fround), lon: Float64Array.from(c.lon, Math.fround),
        mapCell, onViable: bit(c.flags, 2),
        onCf: nums(c.onCf, n),
        country: Array.from(c.country, k => c.countries[k]),
        windNF: nums(c.windNF, n),
        windLcoe: { 2026: nums(c.wl2026, n), 2035: nums(c.wl2035, n), 2050: nums(c.wl2050, n) }
    };
    const multiple = Float64Array.from(c.multiple, (m, i) => (m != null ? m : (mapCell[i] ? Infinity : NaN)));
    const results = {};
    for (const [key, r] of Object.entries(s.results)) {
        results[key] = {
            priced: bit(r.flags, 1), meets: bit(r.flags, 2), nwMeets: bit(r.flags, 4),
            lcoe: nums(r.lcoe, n), nwLcoe: nums(r.nwLcoe, n), saving: nums(r.saving, n), windShare: nums(r.windShare, n)
        };
    }
    return { baseYear: s.baseYear, values: s.values, cells, pot: { multiple }, results };
}

export async function loadSummary(url = SUMMARY_URL) {
    const r = await fetch(url);
    if (!r.ok) throw new Error(`article summary: HTTP ${r.status}`);
    return decodeSummary(await r.json());
}
